  // Retention
  "excludes.advisoryImmichDb": "Immich her fotoğrafın albümlerini, yüzlerini ve tarihlerini kendi ayrı konteynerinde çalışan bir PostgreSQL veritabanında tutar, bu yüzden bu yedek onu içermez. Buradan geri yükleme resimleri bunlar olmadan geri getirir. BombVault o veritabanı konteynerini yedeklerken dökümünü kendiliğinden alır, bu yüzden onun programında olduğundan emin ol.",
  "excludes.advisoryNextcloudDb": "Nextcloud hesapları, paylaşımları ve etiketleri genellikle ayrı bir konteynerde çalışan bir veritabanında tutar, bu yüzden bu yedek onu içermez. Dosyalar geri gelir, paylaşımlar gelmez. BombVault o veritabanı konteynerini yedeklerken dökümünü kendiliğinden alır, bu yüzden onun programında olduğundan emin ol.",
