  "whatsNew.instancesChecking": "BombVault başladıktan hemen sonra bir kart, örneği geri gelene kadar kaybolmuş gibi görünmek yerine Denetleniyor gösterir.",
  "whatsNew.pairingInactive": "Eşleştirme sayfası kapatılmış sunucuları ve uygulaması kapalı telefonları en son ne zaman görüldükleriyle birlikte Etkin değil olarak gösterir.",
