  "whatsNew.signIns": "Paylaşılan bulut kimlik bilgileri ve ek kimlik bilgisi kümeleri, biri varsayılan olan tek bir oturum açma listesidir. Liste hedeflerin altında durur ve hangi hedefin hangi oturum açma bilgisini kullandığını gösterir.",
