  "dbdump.listTitle": "Veritabanı dökümleri",
  "dbdump.listHint": "Her döküm, yedeklemesinden hemen önce çalışan veritabanından alınan tam bir SQL dışa aktarımıdır. BombVault bir dökümü kendiliğinden geri yüklemez: kapsayıcıyı geri almak dosyalarını geri getirir ve bu dosyalar kapsayıcı durmuşken kaydedildiyse daha yeni kopya onlardır. Dökümü, o dosyalar işe yaramadığında kullan: sunucu çalışırken kopyalandılarsa ya da hiç kopyalanmadılarsa, veritabanı yeni bir ana sürüme geçtiyse veya veri klasörü bozulduysa. İçe aktarma dökümü yeni başlatılmış boş bir veritabanına koyar ve eski veri klasörünü yanında tutar. Eksiksiz bir .sql dosyası \"complete\" yorum satırıyla biter.",
