  "mcp.copyConfig": "Yapılandırmayı kopyala",
  "mcp.copySettings": "Ayarları kopyala",
  "mcp.setupCommand": "Bunu bir terminalde bir kez çalıştır.",
  "mcp.setupFile": "Bunu yapılandırma dosyasına, orada zaten bulunan sunucuların yanına ekle.",
  "mcp.setupFileUi": "{app} içinde dosyayı {ui} açar.",
  "mcp.setupPaste": "Bunu {app} içinde {ui} altına da yapıştırabilirsin.",
  "mcp.setupForm": "Bu değerleri {app} içinde {ui} altına gir.",
  "mcp.setupOther": "Streamable HTTP konuşan her istemci olur. Bunları uzak bir MCP sunucusu istediği yere gir, anahtar iki başlıktan birinde olsun.",
  "mcp.setupWhere": "Dosyanın yeri",
  "mcp.setupNeedsNode": "Node.js gerekir, çünkü {app} ile BombVault arasını mcp-remote bağlar.",
  "mcp.keyFileLine": "Anahtarı bir metin dosyasına X-API-Key: <key> satırı olarak kaydet ve o dosyanın yolunu yapılandırmaya yaz. {app} yalnızca yolu saklar, böylece anahtar ne orada ne de işlem listesinde görünür.",
  "mcp.keyFileJsonTip": "Bu JSON dosyasında yolları düz eğik çizgiyle yaz, örneğin C:/Users/sam/bombvault-key.txt, çünkü tek bir ters eğik çizgi geçerli JSON değildir. Anahtar dosyasının yolunda boşluk olmasın: Windows'ta {app}, boşluk içeren bir yolu npx'e iki parça hâlinde verir.",
  "mcp.keyEnv": "{app} anahtarı {var} ortam değişkeninden okur.",
  "mcp.keyEnvTip": "Onu bir kez kullanıcı ortam değişkeni olarak ayarla: Windows'ta Ayarlar, Sistem, Hakkında, Gelişmiş sistem ayarları, Ortam Değişkenleri altında; macOS ve Linux'ta kabuk profilinde. Sonra {app} uygulamasını yeniden başlat. Bir komut satırında setx ya da export ile yazarsan anahtar kabuk geçmişinde kalır. macOS'ta Dock ya da Finder'dan açılan bir uygulama kabuk profilini okumaz: anahtarı tek başına ~/.bombvault-key gibi bir dosyaya koy, Terminal'de launchctl setenv {var} \"$(cat ~/.bombvault-key)\" komutunu çalıştır ve {app} uygulamasını yeniden aç; bunu Mac'in her yeniden başlatılmasından sonra tekrarla.",
  "mcp.keyEnvUnsure": "{app} anahtar yerine değişkenin adını gönderirse anahtarı dosyada onun yerine yaz ve o dosyayı kendine sakla.",
  "mcp.keyPrompt": "{app} sunucuyu ilk başlattığında anahtarı sorar ve kendi gizli bilgi deposunda saklar, yani dosyada anahtar yoktur.",
  "mcp.keyDotenv": "{app} anahtarı {file} içindeki {var}=<key> satırından okur. O dosyayı kendine sakla.",
  "mcp.keyInFile": "{app} anahtarı başka hiçbir yerden okuyamaz, bu yüzden anahtar bu dosyada düz metin olarak durur. Dosyayı kendine sakla; paylaşılan klasörlerden ve sürüm denetiminden uzak tut.",
  "mcp.keyInApp": "{app} anahtarı kendi ayarlarında, belgelerinin söylediği kadarıyla şifrelemeden saklar. O ayarları açabilen herkes onu okuyabilir.",
  "mcp.keyCredential": "{app} anahtarı kimlik bilgileri arasında şifreli saklar: onunla Bearer Auth türünde bir kimlik bilgisi oluştur ve düğümde onu seç. İş akışı yalnızca kimlik bilgisinin adını anar.",
  "mcp.keyVendor": "{app} anahtarı sağlayıcısının sunucularında saklar ve her çağrıyla gönderir.",
  "mcp.keyOther": "İstemci anahtarı bir ortam değişkeninden, bir gizli bilgi isteminden ya da sistemin anahtar zincirinden okuyabiliyorsa, anahtarı ayarlarına yazmak yerine bunu kullan.",
  "mcp.certPlaceholder": "BombVault kendi sertifikasını kullanır. Yapılandırma Node.js'i ona yönlendirir: dosyayı indir ve yolunu sertifika yer tutucusunun yerine yaz.",
  "mcp.certEnv": "BombVault kendi sertifikasını kullanır. {app} onu reddederse {var} ortam değişkenini indirilen dosyanın yoluna ayarla ve {app} uygulamasını yeniden başlat.",
  "mcp.certEnvTip": "Onu kullanıcı ortam değişkenlerini ayarladığın yerde ayarla: Windows'ta Ayarlar, Sistem, Hakkında, Gelişmiş sistem ayarları, Ortam Değişkenleri altında; macOS ve Linux'ta kabuk profilinde; bir kapsayıcıda kendi ayarlarında, dosya içine bağlanmış olarak. BombVault yeni bir sertifika verdiğinde sertifikayı yeniden indir. macOS'ta Dock ya da Finder'dan açılan bir uygulama kabuk profilini okumaz: onun için Terminal'de dosyanın yoluyla launchctl setenv {var} komutunu çalıştır ve uygulamayı yeniden aç; bunu Mac'in her yeniden başlatılmasından sonra tekrarla.",
  "mcp.certSystem": "BombVault kendi sertifikasını kullanır. {app} onu reddederse indirilen dosyayı sisteminin güvenilen sertifikalarına ekle ve {app} uygulamasını yeniden başlat.",
  "mcp.certSystemTip": "Windows'ta dosyanın adını bombvault-cert.crt yap, aç ve Sertifika Yükle, Geçerli Kullanıcı, Tüm sertifikaları aşağıdaki depolama alanına yerleştir, Güvenilen Kök Sertifika Yetkilileri seçeneklerini seç. Ya da dosyanın yoluyla certutil -user -addstore Root komutunu çalıştır. macOS'ta Anahtar Zinciri Erişimi'nde onu oturum açma anahtar zincirine ekle ve Her Zaman Güven olarak ayarla. Linux'ta onu .crt uzantısıyla /usr/local/share/ca-certificates klasörüne kopyala ve update-ca-certificates komutunu çalıştır.",
  "mcp.certOwnList": "BombVault kendi sertifikasını kullanır ve {app} sertifikaları, eklenemeyen kendi listesine göre denetler. BombVault'unkini reddederse BombVault'a herkesçe güvenilen bir sertifikası olan bir ters proxy üzerinden ulaş.",
  "mcp.certOther": "BombVault kendi sertifikasını kullanır. İstemciyi indirilen dosyaya yönlendir ya da onu sisteminin güvenilen sertifikalarına ekle.",
  "mcp.certOtherTip": "Node.js üzerinde çalışan bir istemci dosyayı NODE_EXTRA_CA_CERTS değişkeninden alır. Diğer istemcilerin çoğu sistemin güvendiği sertifikaları kullanır. Sertifika denetimini asla kapatma.",
  "mcp.waitTitle": "İlk çağrı bekleniyor",
  "mcp.connectedTitle": "Bağlandı",
  "mcp.waitLine": "{app} uygulamasının BombVault'u çağırması bekleniyor",
  "mcp.waitLineOther": "İstemcinin BombVault'u çağırması bekleniyor",
  "mcp.waitHint": "Yeni sunucuyu yüklemesi için {app} uygulamasını yeniden başlat, sonra BombVault'u bir kez kullanmasını sağla. İlk çağrıda burası yeşile döner.",
  "mcp.waitHintOther": "İstemciyi bağla. İlk çağrıda burası yeşile döner.",
  "mcp.firstCall": "BombVault ilk çağrıyı {name} anahtarıyla saat {time} sularında {addr} adresinden aldı.",
  "mcp.firstCallNoAddr": "BombVault ilk çağrıyı {name} anahtarıyla saat {time} sularında aldı.",
  "oauth.heading": "BombVault'a erişime izin verilsin mi?",
  "oauth.asks": "{name}, bu BombVault'un MCP sunucusuna erişim istiyor.",
  "oauth.reads": "Yedeklerin durumunu okuyabilecek: neyin korunduğunu, her ögenin en son ne zaman yedeklendiğini, çalıştırmaların nasıl geçtiğini ve günlüklerinde ne yazdığını. Geri yüklemeler, silmeler ve ayarlar bu web arayüzünde kalır.",
  "oauth.unverified": "BombVault bu istemciyi tanımıyor ve yukarıdaki adı istemci kendisi seçti. Yalnızca bu oturum açmayı az önce kendin başlattıysan izin ver.",
  "oauth.startedHere": "Yalnızca bu oturum açmayı az önce kendin başlattıysan izin ver. Başka birinin gönderdiği bir bağlantı, onun {name} hesabını senin BombVault'una bağlayabilir.",
  "oauth.loopback": "Bu istemci kendi bilgisayarındaki bir programa geri döner ve oradaki herhangi bir program kendini o gibi gösterebilir. Yalnızca bu oturum açmayı az önce kendin başlattıysan izin ver.",
  "oauth.allowStartHint": "Bu açıkken istemci ayrıca yedekleme başlatabilir ve kendi başlattıklarını iptal edebilir, bir anahtarla aynı sınırlar içinde. Yedekleme bitene kadar çalışan konteynerleri durdurur. Bunu daha sonra Ayarlar, Entegrasyonlar, MCP sunucusu altında onun kutucuğundan değiştirebilirsin.",
  "oauth.accept": "İzin ver",
  "oauth.decline": "Reddet",
