  "oauth.errorBusy": "Bekleyen çok fazla oturum açma var. Bir dakika sonra yeniden dene.",
  "oauth.errorFailed": "İstek denetlenemedi. Yeniden denemek için sayfayı yenile.",
  "mcp.statusOAuthOnly": "Açık: bir istemcinin OAuth ile oturum açması bekleniyor",
  "mcp.oauthToggle": "OAuth ile oturum açma",
  "mcp.oauthHint": "ChatGPT, claude.ai üzerindeki Claude ve anahtar alamayan diğer hizmetler için. Seni bir BombVault sayfasına gönderirler; orada giriş parolanla oturum açar ve onlara izin verirsin. BombVault'u kendi sunucularından çağırırlar, bu yüzden BombVault aşağıdaki genel adreste internetten erişilebilir olmalı ve tarayıcıların güvendiği bir sertifikası olmalı. Kapatmak tüm istemcilerin oturumunu kapatır.",
