  "mcp.setupClaudeAi": "claude.ai'de Ayarlar, Bağlayıcılar'ı aç ve Özel bağlayıcı ekle'yi seç. Ona bir ad ver, bağlayıcı URL'sini yapıştır, OAuth istemci kimliği ile sırrını boş bırak ve ekle. Ardından Bağlan'ı seç.",
