  "anomaly.settings.hint": "Bir ögenin her yedeğini kendi geçmişiyle karşılaştırır ve uymayanı bildirir. Her yedekten sonra arka planda çalışır ve hiçbirini yavaşlatmaz. Denetimlerin çoğu bir ögenin 10 yedeğinden sonra başlar; hatalar, verinin çoğunun yeniden yazılması ve neredeyse boş bir kaynak baştan denetlenir. Boş alan, yerel depolar ve bunu bildiren rclone depoları için izlenir; Unraid kullanıcı paylaşımında bu, tüm dizinin boş alanıdır.",
